// script.js
const jsContent = `
let vines = [];
const GRAVITY = 0.1;
const STIFFNESS = 0.01;

// Clase para representar una liana/rama
class Vine {
    constructor(x1, y1, x2, y2) {
        // Puntos iniciales y finales de la liana
        this.points = [{ x: x1, y: y1 }, { x: x2, y: y2 }];
        this.history = []; // Para mantener una trayectoria de soporte
        this.maxDepth = 100; // Número máximo de segmentos
        this.baseLength = dist(x1, y1, x2, y2);
        this.setupHistory(x1, y1, x2, y2);
    }

    setupHistory(x1, y1, x2, y2) {
        // Simulación inicial de puntos de soporte para hacerla más orgánica
        // Por simplicidad, simplemente creamos una serie de puntos intermedios
        // para simular que crece desde un anclaje a otro.
        let start = createVector(x1, y1);
        let end = createVector(x2, y2);

        let currentPos = start;
        let prevPos = start;

        for (let i = 0; i < 10; i++) {
            // Generar el siguiente punto basándose en el segmento anterior
            let nextPos = p5.Vector.lerp(currentPos, end, (i + 1) / 10);
            this.history.push(p5.Vector.create(nextPos.x, nextPos.y));
            currentPos = nextPos;
            prevPos = currentPos;
        }
        this.points[0] = p5.createVector(x1, y1);
        this.points[this.points.length - 1] = p5.createVector(x2, y2);
    }

    update() {
        // Aplicar física simple (verificación contra gravedad y tensión)
        for (let i = 1; i < this.points.length - 1; i++) {
            let p = this.points[i];
            let prev = this.points[i - 1];
            let next = this.points[i + 1];

            // Aplicar gravedad solo si no está bien anclado en un punto fijo (simplificación)
            p.y += GRAVITY;

            // Efecto de tensión (Intentar mantener la distancia constante entre puntos vecinos)
            let desiredDist = 5; // Distancia deseada entre segmentos

            // Ajuste básico basado en el punto anterior
            let diffX = p.x - prev.x;
            let diffY = p.y - prev.y;
            let currentDist = dist(prev.x, prev.y, p.x, p.y);

            if (currentDist > desiredDist * 1.1) {
                // Estirar ligeramente hacia atrás si está demasiado lejos
                let ratio = desiredDist / currentDist;
                p.x = prev.x + (p.x - prev.x) * ratio;
                p.y = prev.y + (p.y - prev.y) * ratio;
            }
        }

        // Asegurar que los puntos extremos permanezcan fijos (o reaccionen a la interacción)
        this.points[0].x = this.points[0].x; 
        this.points[0].y = this.points[0].y; 

        this.points[this.points.length - 1].x = this.points[this.points.length - 1].x;
        this.points[this.points.length - 1].y = this.points[this.points.length - 1].y;
    }

    display() {
        stroke(139, 69, 19); // Color marrón/verde oliva
        strokeWeight(3);

        // Dibujar los segmentos de la liana
        for (let i = 0; i < this.points.length - 1; i++) {
            let p1 = this.points[i];
            let p2 = this.points[i + 1];

            // Aplicar una ligera curva o flexión al dibujar, simulando peso
            let dx = p2.x - p1.x;
            let dy = p2.y - p1.y;
            let len = dist(p1.x, p1.y, p2.x, p2.y);

            // Simulación de flexión simple (usando un punto intermedio)
            let midX = p1.x + (p2.x - p1.x) * 0.5;
            let midY = p1.y + (p2.y - p1.y) * 0.5;

            // Curva (más avanzado, pero para hacerlo funcional: dibujamos la línea recta)
            line(p1.x, p1.y, p2.x, p2.y);
        }
    }
}

// =======================================================================
// SETUP y DRAW
// =======================================================================

function setup() {
    // El canvas se establecerá como fullscreen en style.css
    createCanvas(windowWidth, windowHeight);

    // Inicializar algunas lianas de ejemplo al cargar
    // Liana 1: Horizontal en la parte superior izquierda
    vines.push(new Vine(0, height * 0.2, 200, height * 0.2));

    // Liana 2: Diagonal en el centro
    vines.push(new Vine(width * 0.2, height * 0.8, width * 0.8, height * 0.2));

    // Evento de clic para crear nuevas lianas interactivamente
    background(20, 50, 20); // Background inicial más oscuro
}

function draw() {
    // Dibujar un fondo sutilmente diferente para un efecto de 'vida'
    background(20, 50, 20, 50); // Opacidad baja para el rastro

    for (let i = 0; i < vines.length; i++) {
        let vine = vines[i];
        vine.update();
        vine.display();
    }

    // Mostrar interactividad de mouse en tiempo real (ej. un borde reactivo)
    stroke(100, 200, 100, 150);
    strokeWeight(2);
    line(mouseX, mouseY, mouseX + 10, mouseY, FRAME_COUNT % 50 < 30 ? 1 : 0); // Pequeño "efecto de hoja"
}

function mousePressed() {
    // Crear una nueva liana que ancle desde el clic (mouse) hasta un punto fijo
    // Por ejemplo, anclamos el inicio al clic y el final a un punto fijo en la parte superior.
    let startX = mouseX;
    let startY = mouseY;

    // Punto de anclaje fijo en la parte superior para que la liana "salga" de algún lugar
    let endX = random(width * 0.1, width * 0.9);
    let endY = random(height * 0.1, height * 0.2);

    vines.push(new Vine(startX, startY, endX, endY));
}

function windowResized() {
    resizeCanvas(windowWidth, windowHeight);
}
`;
write('script.js', jsContent);
